import {frame} from './model.mjs';
export const steps=[
 {id:'battery',title:'1. ¿La batería sostiene el intento?',part:'crank',electric:'battery',why:'Compara reposo y tensión bajo carga. Si cae en los propios bornes, la energía disponible puede ser insuficiente; no confundas esa caída con la de una conexión.'},
 {id:'command',title:'2. ¿Llega la orden de arranque?',part:'crank',electric:'relay',why:'La orden habilita el solenoide. Sin orden el motor permanece quieto aunque la batería conserve tensión. Hay que investigar el mando, no concluir que el arranque está averiado.'},
 {id:'drop',title:'3. ¿Se pierde tensión en la masa?',part:'crank',electric:'ground',why:'La caída se compara mientras circula corriente. Una caída alta en el retorno explica un giro lento. Un cero sin giro/carga no certifica una conexión sana.'},
 {id:'spark',title:'4. ¿Hay encendido mientras gira?',part:'spark',electric:'starter',why:'Observa la bujía cerca de 360°. Si hay giro pero no encendido, falta una condición de combustión. Sin giro, la ausencia de chispa no identifica una avería del encendido.'},
 {id:'fuel',title:'5. ¿Hay alimentación de combustible?',part:'intake',electric:'starter',why:'La entrega presente o ausente procede de la prueba simulada. La escena no dibuja un caudalímetro: el movimiento del pistón no demuestra que llegue combustible.'},
 {id:'compression',title:'6. ¿El cilindro conserva compresión?',part:'piston',electric:'starter',why:'Compara 11 bar de referencia con la lectura del caso. Una lectura baja indica un problema de sellado o distribución que requiere localizarse. No se deforma el pistón para inventar una causa visible.'},
 {id:'charge',title:'7. ¿Se mantiene en marcha y carga?',part:'crank',electric:'alternator',why:'Suelta la llave después del intento. La referencia puede sostenerse y el caso no. La carga solo se mide con motor en marcha; sin arranque no se debe condenar el alternador.'}
];
export function comparisonValues(actual,reference,id){const a=frame(actual),r=frame(reference),running=id==='charge',valid=running?a.running&&r.running:actual.key==='crank'&&reference.key==='crank'&&(id!=='compression'||a.cranks&&r.cranks);const format=v=>({battery:`${v.rest.toFixed(1)} V reposo → ${v.loaded.toFixed(1)} V durante intento`,command:v.command?'Orden presente':'Orden ausente',drop:`${v.drop.toFixed(2)} V${!v.cranks?' · sin carga: no concluyente':''}`,spark:v.spark?'Encendido detectado':v.cranks?'Encendido no detectado':'Sin giro: no concluyente',fuel:v.fuel?'Entrega presente':'Entrega ausente',compression:`${v.compression} bar`,charge:v.charge===null?'Motor detenido · no medible':`${v.charge.toFixed(1)} V`})[id];return {id,valid,actual:valid?format(a):'Condiciones de prueba pendientes',reference:valid?format(r):'Condiciones de prueba pendientes',different:valid&&format(a)!==format(r),a,r};}
export function visibleDifferences(a,r){const ids=[];if(a.rpm!==r.rpm)ids.push('crank','rod');if(a.spark!==r.spark)ids.push('spark');if(a.combustion!==r.combustion)ids.push('piston');return ids;}
export function advancePair(pair,actual,reference,dt){const speed=v=>v.rpm>0?(v.running?.15:v.rpm/220*.08):0;const d=Math.max(0,Math.min(.05,dt));return {actual:(pair.actual+d*speed(actual))%1,reference:(pair.reference+d*speed(reference))%1};}
